const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Rectangle([-80.5, 42.2, -78.8, 41.2]);
    const startDate1 = '2020-02-22';
    const endDate1 = '2020-02-23';
    const startDate2 = '2020-03-01';
    const endDate2 = '2020-03-02';

    // 2. Data Acquisition & Check
    const snowCoverCollection = ee.ImageCollection('MODIS/061/MOD10A1')
        .select('NDSI_Snow_Cover');

    const collection1 = snowCoverCollection.filterDate(startDate1, endDate1).filterBounds(geometry);
    const collection2 = snowCoverCollection.filterDate(startDate2, endDate2).filterBounds(geometry);

    const size1 = collection1.size().getInfo();
    const size2 = collection2.size().getInfo();

    if (size1 === 0 || size2 === 0) {
        console.log(`Initial image count for Period 1 (Feb 22): ${size1}`);
        console.log(`Initial image count for Period 2 (Mar 1): ${size2}`);
        console.log("Empty Collection: No images found for one or both dates.");
        console.log("A: No"); // In this case, it means no increase because data is absent, interpreted as no snow.
        return;
    }

    // 3. Processing
    const image1 = collection1.mosaic();
    const image2 = collection2.mosaic();

    // The NDSI_Snow_Cover band values > 100 are masks for cloud, water, etc.
    // We mask them out to keep only valid snow cover percentages (0-100).
    const validPixels1 = image1.lte(100);
    const validPixels2 = image2.lte(100);

    const image1_masked = image1.updateMask(validPixels1);
    const image2_masked = image2.updateMask(validPixels2);

    const scale = 1000;

    // 4. Calculation
    const stats1 = image1_masked.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const stats2 = image2_masked.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const mean1 = stats1['NDSI_Snow_Cover_mean'];
    const count1 = stats1['NDSI_Snow_Cover_count'];
    const mean2 = stats2['NDSI_Snow_Cover_mean'];
    const count2 = stats2['NDSI_Snow_Cover_count'];

    // 5. Validation & Final Answer
    if (count1 === 0 || count2 === 0) {
        console.log(`Valid pixel count for Feb 22: ${count1}`);
        console.log(`Valid pixel count for Mar 1: ${count2}`);
        console.log("No Valid Pixels: The region was likely fully clouded on one of the dates.");
        console.log("C2");
        return;
    }

    if (mean1 === null || mean2 === null) {
        console.log("Calculation Failure: Could not compute mean snow cover.");
        console.log("C3");
        return;
    }

    console.log(`Feb 22, 2020: Mean Snow Cover = ${mean1.toFixed(2)}% over ${count1} pixels.`);
    console.log(`Mar 1, 2020: Mean Snow Cover = ${mean2.toFixed(2)}% over ${count2} pixels.`);

    if (mean2 > mean1) {
        console.log("Conclusion: Snow cover increased.");
        console.log("A");
    } else {
        console.log("Conclusion: Snow cover did not increase.");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
